1	// This file pins down the decoder's handling of corrupted *single-byte
2	// markers*: archives whose outer framing, declared payload length and
3	// checksum are all correct, but where one marker byte inside the payload
4	// carries a value the format does not define. The format uses one-byte
5	// markers for booleans (policy Recursive, change RolledBack, subject
6	// Disabled, decision Allowed), for payload presence (the change and
7	// decision payloads) and for list presence (the policy list, the subject
8	// roles and the matched policy list). Only 0 and 1 are legal at every one
9	// of these positions.
10	//
11	// Two failure classes must stay distinguishable. A marker byte of 2, 0xff
12	// or any other undefined value makes the archive uninterpretable: no
13	// non-zero byte may be read as "true" or "present", so the whole read fails
14	// with ErrInvalidArchive and delivers no records — even though the
15	// recomputed outer checksum still matches, proving the rejection comes
16	// from the internal format check. Flipping a boolean between its two legal
17	// values instead keeps the structure readable but changes the audited
18	// content: against the original fingerprints and the caller's retained
19	// checkpoint that is an audit-chain failure, ErrInvalidRange, never a
20	// format error and never a deliverable record.
21	package darksafe
22	
23	import (
24		"bytes"
25		"errors"
26		"fmt"
27		"reflect"
28		"strings"
29		"testing"
30	)
31	
32	// markerEvent is one single-byte marker located in the fixture payload:
33	// its human label, its payload offset and the legal value the fixture
34	// carries there.
35	type markerEvent struct {
36		name  string
37		at    int
38		value byte
39	}
40	
41	// markerFixture builds complete, valid material exercising every marker
42	// kind in both of its legal states: a publish whose two policies carry
43	// Recursive true and false, an allowed decision with populated roles and
44	// matched lists, a publish with a non-nil empty policy set, one with a nil
45	// policy set, a rollback (RolledBack true) and a disabled-subject decision
46	// with nil roles and nil matched list. The chain is semantically
47	// consistent, so the decoded control material still passes offline review.
48	func markerFixture(t *testing.T) ([]byte, []AuditRecord, Checkpoint) {
49		t.Helper()
50		p1 := Policy{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow, Recursive: true}
51		p2 := Policy{ID: "p2", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow, ResourceID: "r1"}
52		enabledReq := request("acme", "u1", "r1", "org/a", "read")
53		enabledReq.Subject.Roles = []string{"role-a", "role-b"}
54		disabledReq := request("acme", "u1", "r1", "org/a", "read")
55		disabledReq.Subject.Disabled = true
56	
57		recs, cp := syntheticChain("acme", []func(int) (string, *PolicyChange, *DecisionRecord){
58			func(seq int) (string, *PolicyChange, *DecisionRecord) {
59				return AuditPolicyChange, &PolicyChange{Version: 1, Policies: []Policy{p1, p2}}, nil
60			},
61			func(seq int) (string, *PolicyChange, *DecisionRecord) {
62				return AuditDecision, nil, &DecisionRecord{
63					Request:  enabledReq,
64					Decision: Decision{Allowed: true, Reason: "matched allow policy", Matched: []string{"p1", "p2"}, Version: 1},
65				}
66			},
67			func(seq int) (string, *PolicyChange, *DecisionRecord) {
68				return AuditPolicyChange, &PolicyChange{Version: 2, Policies: []Policy{}}, nil
69			},
70			func(seq int) (string, *PolicyChange, *DecisionRecord) {
71				return AuditPolicyChange, &PolicyChange{Version: 3, Policies: nil}, nil
72			},
73			func(seq int) (string, *PolicyChange, *DecisionRecord) {
74				return AuditPolicyChange, &PolicyChange{Version: 4, SourceVersion: 1, RolledBack: true, Policies: []Policy{p1, p2}}, nil
75			},
76			func(seq int) (string, *PolicyChange, *DecisionRecord) {
77				return AuditDecision, nil, &DecisionRecord{
78					Request:  disabledReq,
79					Decision: Decision{Allowed: false, Reason: "subject is disabled", Version: 0},
80				}
81			},
82		})
83		archive, err := EncodeAuditArchive("acme", recs, cp)
84		if err != nil {
85			t.Fatalf("encode marker fixture: %v", err)
86		}
87		return archive, recs, cp
88	}
89	
90	// walkMarkerPayload mirrors archiveReader over the marker fixture payload,
91	// recording every single-byte marker (booleans, payload presence, list
92	// presence) with its offset. It exists only to locate the bytes the tests
93	// corrupt; it follows the markers it reads, so a format change desyncs the
94	// walk and fails the fixture-layout expectation loudly rather than letting
95	// a test corrupt the wrong field.
96	func walkMarkerPayload(t *testing.T, p []byte) []markerEvent {
97		t.Helper()
98		c := &payloadInspector{b: p}
99		var events []markerEvent
100		mark := func(name string) {
101			// Read the offset before consuming the byte: evaluation order of the
102			// two reads matters and must not be left to a composite literal.
103			at := c.pos
104			events = append(events, markerEvent{name: name, at: at, value: c.marker()})
105		}
106		last := func() byte { return events[len(events)-1].value }
107		stringList := func(name string) {
108			mark(name)
109			if last() == archiveTagNil {
110				return
111			}
112			n := c.u32()
113			for i := 0; i < n; i++ {
114				c.str()
115			}
116		}
117		policyList := func(name string, rec int) {
118			mark(name)
119			if last() == archiveTagNil {
120				return
121			}
122			n := c.u32()
123			for i := 0; i < n; i++ {
124				c.str() // ID
125				c.str() // Subject
126				c.str() // Action
127				c.str() // Scope
128				c.str() // Effect
129				mark(fmt.Sprintf("record %d policy %d recursive", rec, i))
130				c.str() // ResourceID
131			}
132		}
133	
134		c.str()    // embedded org
135		c.pos += 4 // embedded end sequence
136		c.str()    // embedded checkpoint fingerprint
137		n := c.u32()
138		for rec := 1; rec <= n; rec++ {
139			c.str()    // org
140			c.pos += 4 // seq
141			c.str()    // kind
142			mark(fmt.Sprintf("record %d change payload", rec))
143			if last() == archiveTagPresent {
144				c.pos += 4 // change version
145				policyList(fmt.Sprintf("record %d policy list", rec), rec)
146				c.pos += 4 // source version
147				mark(fmt.Sprintf("record %d rolled back", rec))
148			}
149			mark(fmt.Sprintf("record %d decision payload", rec))
150			if last() == archiveTagPresent {
151				c.str() // request SubjectOrg
152				c.str() // request ResourceOrg
153				c.str() // subject ID
154				c.str() // subject kind
155				stringList(fmt.Sprintf("record %d subject roles", rec))
156				mark(fmt.Sprintf("record %d subject disabled", rec))
157				c.str() // resource ID
158				c.str() // resource scope
159				c.str() // action
160				mark(fmt.Sprintf("record %d decision allowed", rec))
161				c.str() // decision reason
162				stringList(fmt.Sprintf("record %d matched policies", rec))
163				c.pos += 4 // decision version
164			}
165			c.str() // prev fingerprint
166			c.str() // own fingerprint
167		}
168		if c.pos != len(p) {
169			t.Fatalf("marker walk ended at %d, payload length %d", c.pos, len(p))
170		}
171		return events
