package darksafe

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"os"
	"testing"
)

// TestGoldenByteEquivalence is a temporary refactor-verification harness:
// with GOLDEN_WRITE set it dumps comprehensive archives; otherwise it
// compares the current encoder byte-for-byte against the dumped archives.
func TestGoldenByteEquivalence(t *testing.T) {
	invalid := string([]byte{0xff, 0xfe})
	p1 := Policy{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow, Recursive: true}
	p2 := Policy{ID: "p 2 中\t\r\n", Subject: "主\t体 ", Action: "读", Scope: "org/a", Effect: EffectAllow, ResourceID: "r" + invalid}

	recs, cp := syntheticChain("acme", []func(int) (string, *PolicyChange, *PolicyChange){}, nil2(p1, p2, invalid))
	_ = recs
	_ = cp

	archives := buildGoldenArchives(t, p1, p2, invalid)

	if os.Getenv("GOLDEN_WRITE") != "" {
		for name, data := range archives {
			if err := os.WriteFile("/tmp/golden_"+name+".bin", data, 0o644); err != nil {
				t.Fatal(err)
			}
		}
		return
	}
	for name, data := range archives {
		golden, err := os.ReadFile("/tmp/golden_" + name + ".bin")
		if err != nil {
			t.Fatal(err)
		}
		if !bytes.Equal(data, golden) {
			t.Fatalf("archive %q differs: new=%d bytes golden=%d bytes", name, len(data), len(golden))
		}
		// Existing golden archives must still decode directly.
		got, err := DecodeAuditArchive(golden, "acme", cp)
		if err != nil {
			t.Fatalf("golden %q must decode: %v", name, err)
		}
		if !reflectDeepEqualRecords(got, recsFor(name, t, p1, p2, invalid)) {
			t.Fatalf("golden %q decoded mismatch", name)
		}
	}
}

func init() {}

var _ = sha256.Size
var _ = binary.BigEndian

