package darksafe

import (
	"bytes"
	"os"
	"reflect"
	"testing"
)

// TestZZGoldenByteEquivalence is a temporary harness for the list-encoding
// refactor: GOLDEN_WRITE=1 dumps archives of every list shape; a normal run
// compares the current encoder against the dumped bytes and decodes them.
func TestZZGoldenByteEquivalence(t *testing.T) {
	invalid := string([]byte{0xff, 0xfe, 0x00, ' ', '中'})
	p1 := Policy{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow, Recursive: true}
	p2 := Policy{ID: "p 2 中\t\r\n", Subject: "主\t体 ", Action: "读", Scope: "org/a", Effect: EffectAllow, ResourceID: "r" + invalid}

	req := request("acme", "u1", "r1", "org/a", "读")
	payloads := []func(int) (string, *PolicyChange, *DecisionRecord){
		// change: nil policy list
		func(int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{Version: 1, Policies: nil}, nil
		},
		// change: non-nil empty
		func(int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{Version: 2, SourceVersion: 1, RolledBack: true, Policies: []Policy{}}, nil
		},
		// change: multiple policies with raw bytes / fixed order
		func(int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{Version: 3, Policies: []Policy{p1, p2}}, nil
		},
		// decision: nil string lists
		func(int) (string, *PolicyChange, *DecisionRecord) {
			r := req
			r.Subject.Roles = nil
			return AuditDecision, nil, &DecisionRecord{
				Request:  r,
				Decision: Decision{Allowed: true, Reason: "理" + invalid + "由", Matched: nil, Version: 3},
			}
		},
		// decision: non-nil empty lists
		func(int) (string, *PolicyChange, *DecisionRecord) {
			r := req
			r.Subject.Roles = []string{}
			return AuditDecision, nil, &DecisionRecord{
				Request:  r,
				Decision: Decision{Allowed: false, Reason: " ", Matched: []string{}, Version: 3},
			}
		},
		// decision: populated, raw bytes, duplicates kept, order kept
		func(int) (string, *PolicyChange, *DecisionRecord) {
			r := req
			r.Subject.Roles = []string{"zeta", "zeta", "角色 " + invalid}
			return AuditDecision, nil, &DecisionRecord{
				Request: r,
				Decision: Decision{Allowed: true, Reason: "matched allow policy",
					Matched: []string{"p1", "p1", "p" + invalid}, Version: 3},
			}
		},
	}
	recs, cp := syntheticChain("acme", payloads)

	var archives [][]byte
	for n := 1; n <= len(recs); n++ {
		prefixCP := Checkpoint{Org: "acme", EndSeq: n, Fingerprint: recs[n-1].Fingerprint}
		a, err := EncodeAuditArchive("acme", recs[:n], prefixCP)
		if err != nil {
			t.Fatalf("encode prefix %d: %v", n, err)
		}
		archives = append(archives, a)
	}
	// The empty organization as well.
	empty, err := EncodeAuditArchive("acme", []AuditRecord{}, Checkpoint{Org: "acme"})
	if err != nil {
		t.Fatal(err)
	}
	archives = append([][]byte{empty}, archives...)

	if os.Getenv("GOLDEN_WRITE") != "" {
		for i, a := range archives {
			if err := os.WriteFile(goldenPath(i), a, 0o644); err != nil {
				t.Fatal(err)
			}
		}
		return
	}

	for i, a := range archives {
		golden, err := os.ReadFile(goldenPath(i))
		if err != nil {
			t.Fatal(err)
		}
		if !bytes.Equal(a, golden) {
			t.Fatalf("prefix %d: encoding differs from pre-refactor bytes (new=%d golden=%d)", i, len(a), len(golden))
		}
	}

	// Every pre-refactor archive decodes, with exact material equivalence.
	for i := range archives {
		golden, _ := os.ReadFile(goldenPath(i))
		var wantCP Checkpoint
		var want []AuditRecord
		if i == 0 {
			wantCP = Checkpoint{Org: "acme"}
			want = []AuditRecord{}
		} else {
			wantCP = Checkpoint{Org: "acme", EndSeq: i, Fingerprint: recs[i-1].Fingerprint}
			want = recs[:i]
		}
		got, err := DecodeAuditArchive(golden, "acme", wantCP)
		if err != nil {
			t.Fatalf("prefix %d: old archive no longer decodes: %v", i, err)
		}
		if (i == 0 && len(got) != 0) || (i > 0 && !reflect.DeepEqual(got, want)) {
			t.Fatalf("prefix %d: decoded material mismatch\ngot=%+v\nwant=%+v", i, got, want)
		}
	}
}

func goldenPath(i int) string {
	return "/tmp/darksafe_golden_" + string(rune('a'+i)) + ".bin"
}

